{"src/runTasks.mjs":"/** tasks是无参数异步函数数组，concurrency是并发上限；返回Promise。 */
export function runTasks(tasks, concurrency) {
  if (!Array.isArray(tasks)) {
    return Promise.reject(new TypeError('tasks must be an array of functions'));
  }

  const total = tasks.length;
  if (total === 0) {
    return Promise.resolve([]);
  }

  for (let i = 0; i < total; i += 1) {
    if (typeof tasks[i] !== 'function') {
      return Promise.reject(new TypeError(`tasks[${i}] must be a function`));
    }
  }

  let limit = concurrency;
  if (limit === undefined || limit === null) {
    limit = total;
  }
  if (typeof limit !== 'number' || Number.isNaN(limit) || !Number.isFinite(limit)) {
    return Promise.reject(new TypeError('concurrency must be a finite number'));
  }
  limit = Math.floor(limit);
  if (limit < 1) {
    limit = 1;
  }
  if (limit > total) {
    limit = total;
  }

  return new Promise((resolve, reject) => {
    const results = new Array(total);
    let nextIndex = 0;
    let running = 0;
    let completed = 0;
    let settled = false;

    function fail(error) {
      if (settled) {
        return;
      }
      settled = true;
      reject(error);
    }

    function launch() {
      if (settled) {
        return;
      }
      while (running < limit && nextIndex < total) {
        const index = nextIndex;
        nextIndex += 1;
        running += 1;

        let promise;
        try {
          promise = Promise.resolve(tasks[index]());
        } catch (error) {
          fail(error);
          return;
        }

        promise.then(
          value => {
            if (settled) {
              return;
            }
            results[index] = value;
            running -= 1;
            completed += 1;
            if (completed === total) {
              settled = true;
              resolve(results);
              return;
            }
            launch();
          },
          error => {
            fail(error);
          }
        );
      }
    }

    launch();
  });
}
